```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Save Text Form</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            margin: 20px;
        }
        form {
            max-width: 400px;
            margin: 0 auto;
        }
        input[type="text"] {
            width: 100%;
            padding: 10px;
            margin-bottom: 10px;
        }
        button {
            padding: 10px 20px;
            background-color: #007BFF;
            color: white;
            border: none;
            cursor: pointer;
        }
        button:hover {
            background-color: #0056b3;
        }
        #savedText {
            margin-top: 20px;
            font-size: 1.2em;
        }
    </style>
</head>
<body>

    <h1>Save Your Text</h1>
    <form id="textForm">
        <label for="userText">Enter your text:</label>
        <input type="text" id="userText" name="userText" required>
        <button type="submit">Save</button>
    </form>

    <div id="savedText">
        <p>Saved Text:</p>
        <p id="displayText"></p>
    </div>

    <script>
        // Function to save text to local storage
        function saveText() {
            const userText = document.getElementById('userText').value;
            localStorage.setItem('savedText', userText);
            displaySavedText();
        }

        // Function to display saved text
        function displaySavedText() {
            const savedText = localStorage.getItem('savedText');
            if (savedText) {
                document.getElementById('displayText').textContent = savedText;
            } else {
                document.getElementById('displayText').textContent = 'No text saved yet.';
            }
        }

        // Event listener for form submission
        document.getElementById('textForm').addEventListener('submit', function(event) {
            event.preventDefault(); // Prevent form from submitting normally
            saveText(); // Save the text to local storage
        });

        // Display saved text when the page loads
        displaySavedText();
    </script>

</body>
</html>
```

