        document.getElementById('ssnForm').addEventListener('submit', function(event) {
            event.preventDefault(); // 阻止表单默认提交行为

            // 获取输入的SSN
            const ssn = document.getElementById('ssn').value;
            const ssnError = document.getElementById('ssnError');

            // 基本验证：SSN长度应为11位数字
            if (!/^\d{3}-\d{2}-\d{4}$/.test(ssn)) {
                ssnError.textContent = '社会安全号码格式不正确，请输入正确的SSN格式 (XXX-XX-XXXX)';
                return;
            }

            // 如果验证通过，可以继续提交表单
            // 例如：调用服务器端验证或进行其他处理
            alert('社会安全号码格式正确，可以继续提交表单。');
        });
    </script>
</body>
</html>
